package dev.zomboid.lriso;import net.minecraft.client.Minecraft;import com.cleannrooster.dungeons_iso.mod.Mod;import org.lwjgl.glfw.GLFW;import me.xjqsh.lrtactical.client.input.AttackKeys;public class Checks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError(n);}public static class Hit {public net.minecraft.world.phys.Vec3 getLocation(){return new net.minecraft.world.phys.Vec3(3,0,0);}public String getType(){return "BLOCK";}}public static class Box {public net.minecraft.world.phys.Vec3 getCenter(){return new net.minecraft.world.phys.Vec3(3,1,0);}}public static class Enemy {public Box getBoundingBox(){return new Box();}}public static class EntityHit extends Hit {public String getType(){return "ENTITY";}public Enemy getEntity(){return new Enemy();}}
public static void main(String[] args){GLFW.pressed=true;check(Input.held(false));GLFW.pressed=false;check(!Input.held(false));check(Input.held(true));GLFW.pressed=true;Minecraft.M.screen=new Object();check(!Input.held(false));Minecraft.M.screen=null;Mod.enabled=false;check(!Input.held(false));Mod.enabled=true;Minecraft.M.active=false;check(!Input.held(false));Minecraft.M.active=true;AttackKeys.NORMAL_ATTACK.modifier=net.neoforged.neoforge.client.settings.KeyModifier.CTRL;check(!Input.held(false));AttackKeys.NORMAL_ATTACK.modifier=net.neoforged.neoforge.client.settings.KeyModifier.NONE;Mod.crosshairTarget=new Hit();var vector=(net.minecraft.world.phys.Vec3)Input.look(Minecraft.M.player);check(Math.abs(vector.x-1)<.001&&Math.abs(vector.y)<.001&&Math.abs(Minecraft.M.player.yaw+90)<.001);Minecraft.M.player.yaw=180;Minecraft.M.player.pitch=-80;vector=(net.minecraft.world.phys.Vec3)Input.look(Minecraft.M.player);check(Math.abs(vector.x-1)<.001&&Math.abs(vector.y)<.001&&Math.abs(Minecraft.M.player.yaw+90)<.001);Mod.enabled=false;vector=(net.minecraft.world.phys.Vec3)Input.look(Minecraft.M.player);check(vector.z==1);Mod.enabled=true;Mod.crosshairTarget=new EntityHit();vector=(net.minecraft.world.phys.Vec3)Input.look(Minecraft.M.player);check(vector.x>.9&&vector.y<0&&Minecraft.M.player.pitch>0);check(Math.abs(vector.x*vector.x+vector.y*vector.y+vector.z*vector.z-1)<.001);System.out.println("Passed "+n+" isometric input and direction checks (API doubles)");}}
